css:
html{-webkit-text-size-adjust:100%}
body{margin:0;background:#F9F4EC}
.bt-pg{--navy:#004877;--ink:#1d1e1f;--cream:#F9F4EC;--sand:#F3E9D9;--sky:#3C96E7;--pale:#AED3F5;--line:rgba(0,72,119,.16);--line2:rgba(0,72,119,.08);--mut:rgba(0,72,119,.66);--body:rgba(29,30,31,.78);--serif:"Bodoni Moda","Bodoni MT",Didot,Georgia,serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);display:block;font-family:var(--sans);font-size:16.5px;line-height:1.65;color:var(--ink);background:var(--cream);-webkit-font-smoothing:antialiased;font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-pg *,.bt-pg *::before,.bt-pg *::after{box-sizing:border-box}
.bt-pg a{color:inherit;text-decoration:none}
.bt-pg p{margin:0}
.bt-pg ul,.bt-pg ol{list-style:none;margin:0;padding:0}
.bt-pg img{display:block;max-width:100%}
.bt-pg button,.bt-pg input,.bt-pg select,.bt-pg textarea{font-family:inherit;color:inherit}
.bt-pg svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.bt-pg [hidden]{display:none!important}
.bt-pg a:focus-visible,.bt-pg button:focus-visible,.bt-pg input:focus-visible,.bt-pg select:focus-visible,.bt-pg textarea:focus-visible,.bt-pg label:focus-visible{outline:2px solid var(--sky);outline-offset:2px}
.bt-pg .bt-js-only{display:none}
html.bt-js .bt-pg .bt-js-only{display:block}
html.bt-js .bt-pg .bt-nojs{display:none}
.bt-pg .bt-wrap{max-width:1472px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.bt-pg h1,.bt-pg h2,.bt-pg h3{font-family:var(--serif);font-weight:400;letter-spacing:-.012em;margin:0;text-wrap:balance}
.bt-pg h1{font-size:clamp(40px,5.4vw,76px);line-height:1.02}
.bt-pg h2{font-size:clamp(30px,3.2vw,46px);line-height:1.08}
.bt-pg h1 em,.bt-pg h2 em{font-style:italic;color:var(--navy)}
.bt-pg .bt-kicker{display:flex;align-items:center;gap:14px;font-size:12.5px;line-height:1;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:var(--navy);margin-bottom:22px}
.bt-pg .bt-kicker::before{content:"";width:40px;height:1px;background:currentColor;flex:none}
.bt-pg .bt-lead{color:var(--body);max-width:56ch;margin-top:20px}
.bt-pg .bt-crumbs{display:flex;flex-wrap:wrap;gap:10px;font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);margin-bottom:clamp(24px,3vw,40px)}
.bt-pg .bt-crumbs a:hover{color:var(--navy)}
.bt-pg .bt-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:0 28px;font-family:var(--sans);font-size:12.5px;line-height:1.2;font-weight:500;letter-spacing:.2em;text-transform:uppercase;text-align:center;border:1px solid var(--navy);border-radius:2px;background:var(--navy);color:#fff;cursor:pointer;transition:background .5s var(--ease),color .5s var(--ease),border-color .5s var(--ease),gap .5s var(--ease)}
.bt-pg .bt-btn:hover{background:transparent;color:var(--navy);gap:16px}
.bt-pg .bt-btn svg{width:14px;height:14px}
.bt-pg .bt-btn-line{background:transparent;color:var(--navy)}
.bt-pg .bt-btn-line:hover{background:var(--navy);color:#fff}
.bt-pg .bt-btn-cream{background:var(--cream);border-color:var(--cream);color:var(--navy)}
.bt-pg .bt-btn-cream:hover{background:transparent;color:var(--cream)}
.bt-pg .bt-btn-block{display:flex;width:100%}
.bt-pg .bt-link{display:inline-flex;align-items:center;gap:10px;font-size:12px;line-height:1.2;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--navy);border:0;border-bottom:1px solid currentColor;background:none;padding:0 0 6px;cursor:pointer;transition:gap .5s var(--ease)}
.bt-pg .bt-link:hover{gap:16px}
.bt-pg .bt-link svg{width:14px;height:14px}
.bt-pg .bt-top{padding:clamp(28px,3.4vw,52px) 0 clamp(30px,3.6vw,56px);border-bottom:1px solid var(--line)}
.bt-pg .bt-top-in{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:clamp(24px,4vw,72px);align-items:end}
/* three step flow: equal columns, tile centred over its label, one line between each pair of tiles */
.bt-pg .bt-flow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));width:450px;max-width:100%;perspective:600px}
.bt-pg .bt-flow li{position:relative;display:flex;flex-direction:column;align-items:center;gap:12px;min-width:0;text-align:center;font-size:11px;line-height:1.3;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut)}
.bt-pg .bt-flow li+li::before{content:"";position:absolute;top:18px;right:calc(50% + 28px);width:calc(100% - 56px);height:1px;background:var(--line)}
.bt-pg .bt-flow li.bt-on::before,.bt-pg .bt-flow li.bt-done::before{background:var(--navy)}
.bt-pg .bt-flow a{display:flex;flex-direction:column;align-items:center;gap:12px}
.bt-pg .bt-flow i{display:flex;align-items:center;justify-content:center;width:38px;height:38px;border:1px solid var(--line);font-family:var(--serif);font-style:normal;font-size:18px;line-height:1;letter-spacing:0;color:var(--navy);background:var(--cream)}
.bt-pg .bt-flow .bt-on,.bt-pg .bt-flow .bt-done{color:var(--navy)}
.bt-pg .bt-flow .bt-on i,.bt-pg .bt-flow .bt-done i{background:var(--navy);border-color:var(--navy);color:#fff}
.bt-pg .bt-flow .bt-on i{box-shadow:0 14px 22px -12px rgba(0,72,119,.8);animation:btFlowFlip 1.1s var(--ease) both}
.bt-pg .bt-flow .bt-done svg{width:16px;height:16px;stroke-width:2}
.bt-pg .bt-flow a:hover i{background:var(--cream);color:var(--navy)}
@keyframes btFlowFlip{from{transform:rotateY(-180deg)}to{transform:none}}
.bt-pg .bt-sec{padding:clamp(36px,4.6vw,72px) 0 clamp(64px,8vw,120px)}
/* shared navy panel with a tiled floor */
.bt-pg .bt-navy{position:relative;isolation:isolate;overflow:hidden;color:#fff;background:linear-gradient(160deg,#004877 0%,#00365b 46%,#001a2e 100%)}
.bt-pg .bt-floor{position:absolute;left:0;right:0;bottom:0;z-index:-1;height:190px;overflow:hidden;perspective:340px;perspective-origin:50% 0;opacity:.5;pointer-events:none;-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 70%);mask-image:linear-gradient(180deg,transparent 0,#000 70%)}
.bt-pg .bt-floor i{position:absolute;left:-120%;right:-120%;top:0;height:900px;transform-origin:50% 0;transform:translateZ(-300px) rotateX(76deg);background-image:linear-gradient(rgba(174,211,245,.42) 1.5px,transparent 1.5px),linear-gradient(90deg,rgba(174,211,245,.42) 1.5px,transparent 1.5px);background-size:74px 74px;animation:btPgFloor 18s linear infinite}
@keyframes btPgFloor{to{background-position:0 148px}}
.bt-pg .bt-ticks li{position:relative;padding-left:22px;font-size:14.5px;line-height:1.5}
.bt-pg .bt-ticks li+li{margin-top:10px}
.bt-pg .bt-ticks li::before{content:"";position:absolute;left:1px;top:7px;width:7px;height:7px;border:1px solid currentColor;transform:rotate(45deg);opacity:.9}
/* product thumb used in cart lines and summaries */
.bt-pg .bt-line-img{position:relative;display:block;overflow:hidden;background:var(--sand);box-shadow:0 0 0 1px var(--line)}
.bt-pg .bt-line-img img{width:100%;height:100%;object-fit:cover}
.bt-pg .bt-line-img:empty::after{content:"";position:absolute;left:50%;top:50%;width:34%;height:34%;margin:-17% 0 0 -17%;border:1px solid var(--mut);transform:rotate(45deg)}
.bt-pg .bt-sum-line{display:grid;grid-template-columns:58px minmax(0,1fr) auto;gap:14px;align-items:start;padding:16px 0;border-bottom:1px solid var(--line)}
.bt-pg .bt-sum-line .bt-line-img{width:58px;height:58px}
.bt-pg .bt-sum-t{font-family:var(--serif);font-size:19px;line-height:1.15}
.bt-pg .bt-sum-m,.bt-pg .bt-sum-q{font-size:13.5px;line-height:1.45;color:var(--body);margin-top:3px}
.bt-pg .bt-sum-e{font-weight:500;font-size:15px;color:var(--navy);white-space:nowrap;padding-top:2px}
@media (max-width:900px){
.bt-pg .bt-top-in{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:760px){
.bt-pg{font-size:16px}
.bt-pg .bt-sec{padding-bottom:calc(88px + env(safe-area-inset-bottom))}
.bt-pg .bt-flow{width:100%}
.bt-pg .bt-flow li{font-size:10px;letter-spacing:.12em}
}
@media (prefers-reduced-motion:reduce){.bt-pg *,.bt-pg *::before,.bt-pg *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.bt-pg .bt-floor i{animation:none!important}}
/* product cards and grids */
.bt-pg .bt-pgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(12px,1.5vw,24px);perspective:2000px}
.bt-pg .bt-pc{position:relative;display:flex;flex-direction:column;min-width:0;color:var(--ink);background:var(--cream);box-shadow:0 0 0 1px var(--line);transition:transform .9s var(--ease),box-shadow .9s var(--ease)}
.bt-pg .bt-pc:hover,.bt-pg .bt-pc:focus-within{transform:translateY(-8px) rotateX(2.5deg);box-shadow:0 0 0 1px var(--line),0 40px 50px -36px rgba(17,18,19,.6)}
.bt-pg .bt-pc-img{position:relative;display:block;aspect-ratio:4/3;overflow:hidden;background:var(--sand)}
.bt-pg .bt-pc-img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform 1.6s var(--ease),opacity .7s var(--ease)}
.bt-pg .bt-pc:hover .bt-pc-img img{transform:scale(1.06)}
.bt-pg .bt-pc-img .bt-pc-r{opacity:0}
.bt-pg .bt-pc:hover .bt-pc-img .bt-pc-r,.bt-pg .bt-pc:focus-within .bt-pc-img .bt-pc-r{opacity:1}
.bt-pg .bt-pc-sq .bt-pc-img{aspect-ratio:1;background:#fff}
.bt-pg .bt-pc-ph{display:flex;align-items:center;justify-content:center}
.bt-pg .bt-pc-ph::after{content:"";width:22%;aspect-ratio:1;border:1px solid var(--mut);transform:rotate(45deg)}
.bt-pg .bt-badge{position:absolute;left:0;top:14px;z-index:1;background:var(--navy);color:#fff;font-size:10px;line-height:1;font-weight:500;letter-spacing:.2em;text-transform:uppercase;padding:8px 11px}
.bt-pg .bt-pc-tag{position:absolute;right:10px;bottom:10px;z-index:1;background:rgba(17,18,19,.72);color:#fff;font-size:10px;line-height:1;font-weight:500;letter-spacing:.16em;text-transform:uppercase;padding:7px 9px;opacity:0;transition:opacity .6s var(--ease)}
.bt-pg .bt-pc:hover .bt-pc-tag{opacity:1}
.bt-pg .bt-pc-b{display:flex;flex-direction:column;flex:1;padding:18px 18px 20px}
.bt-pg .bt-pc-k{font-size:10.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
.bt-pg .bt-pc h3{font-size:clamp(20px,1.7vw,25px);line-height:1.12;margin:6px 0 4px;overflow-wrap:anywhere}
.bt-pg .bt-pc-k,.bt-pg .bt-pc-m{overflow-wrap:anywhere}
.bt-pg .bt-pc h3 a:hover{color:var(--navy)}
.bt-pg .bt-pc-m{font-size:13.5px;line-height:1.45;color:var(--body)}
.bt-pg .bt-pc-p{font-size:13.5px;color:var(--body);margin-top:8px}
.bt-pg .bt-pc-p b{font-family:var(--serif);font-weight:400;font-size:22px;line-height:1;color:var(--navy)}
.bt-pg .bt-pc-cta{display:flex;gap:8px;margin-top:auto;padding-top:16px}
.bt-pg .bt-pc-cta .bt-btn{flex:1;min-height:48px;padding:0 10px;font-size:11px;letter-spacing:.16em}
.bt-pg .bt-pc-ico{display:inline-flex;align-items:center;justify-content:center;flex:none;width:48px;height:48px;border:1px solid var(--navy);border-radius:2px;color:var(--navy);transition:background .4s var(--ease),color .4s var(--ease)}
.bt-pg .bt-pc-ico:hover{background:var(--navy);color:#fff}
/* tile cards: tile and inspiration tabs, quick view (same features as the home page cards) */
.bt-pg .bt-vh{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.bt-pg .bt-qv,.bt-pg .bt-cv{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-pg .bt-qv0{position:fixed}
.bt-pg .bt-slot{position:relative;display:flex;min-width:0}
.bt-pg .bt-tc{width:100%}
.bt-pg .bt-tc-imgs{position:relative;display:block;aspect-ratio:4/3;overflow:hidden;background:var(--sand)}
.bt-pg .bt-ci{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:opacity .8s var(--ease),transform 1.6s var(--ease)}
.bt-pg .bt-tc:hover .bt-ci{transform:scale(1.05)}
.bt-pg .bt-ci-r{opacity:0}
.bt-pg .bt-cv-r:checked~.bt-tc-media .bt-ci-r{opacity:1}
.bt-pg .bt-cv-r:checked~.bt-tc-media .bt-ci-s{opacity:0}
.bt-pg .bt-tc-ph{display:flex;align-items:center;justify-content:center}
.bt-pg .bt-tc-ph::after{content:"";width:22%;aspect-ratio:1;border:1px solid var(--mut);transform:rotate(45deg)}
.bt-pg .bt-seg{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line)}
.bt-pg .bt-seg label{display:flex;align-items:center;justify-content:center;min-height:40px;padding:0 6px;font-size:10.5px;line-height:1.15;font-weight:500;letter-spacing:.16em;text-transform:uppercase;text-align:center;cursor:pointer;background:#fff;color:var(--ink);transition:background .4s var(--ease),color .4s var(--ease)}
.bt-pg .bt-seg label+label{border-left:1px solid var(--line)}
.bt-pg .bt-cv-s:checked~.bt-tc-media .bt-seg-s,.bt-pg .bt-cv-r:checked~.bt-tc-media .bt-seg-r{background:var(--ink);color:#fff}
.bt-pg .bt-cv-s:focus-visible~.bt-tc-media .bt-seg-s,.bt-pg .bt-cv-r:focus-visible~.bt-tc-media .bt-seg-r{outline:2px solid var(--sky);outline-offset:-3px}
.bt-pg .bt-tc .bt-pc-cta label.bt-btn{background:var(--navy);color:#fff}
.bt-pg .bt-tc .bt-pc-cta label.bt-btn:hover{background:var(--ink);border-color:var(--ink)}
.bt-pg .bt-qv-only,.bt-pg .bt-qv-x,.bt-pg .bt-qv-scrim{display:none}
.bt-pg .bt-slot:has(.bt-qv:checked)>.bt-qv-scrim{display:block;position:fixed;inset:0;z-index:999;background:rgba(17,18,19,.66);cursor:pointer;animation:btQvFade .5s var(--ease) both}
.bt-pg .bt-pgrid:has(.bt-qv:checked){perspective:none}
.bt-pg .bt-navy:has(.bt-qv:checked){z-index:1000;overflow:visible}
html:has(.bt-pg .bt-qv:not(.bt-qv0):checked){overflow:hidden}
@keyframes btQvFade{from{opacity:0}to{opacity:1}}
@keyframes btQv{from{opacity:0;transform:translate(-50%,-46%) scale(.97)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
@keyframes btQvM{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}
.bt-pg .bt-tc:has(>.bt-qv:checked){position:fixed;z-index:1000;left:50%;top:50%;transform:translate(-50%,-50%);width:min(1180px,calc(100vw - 48px));height:min(790px,calc(100vh - 48px));display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);grid-template-rows:minmax(0,1fr);background:var(--cream);overflow:hidden;animation:btQv .6s var(--ease) both;box-shadow:0 60px 120px -40px rgba(0,0,0,.7);transition:none}
.bt-pg .bt-qv:checked~.bt-tc-media{display:flex;flex-direction:column;min-height:0;min-width:0;background:var(--sand)}
.bt-pg .bt-qv:checked~.bt-tc-media .bt-tc-imgs{flex:1;aspect-ratio:auto;min-height:0}
.bt-pg .bt-qv:checked~.bt-tc-media .bt-ci{transform:none}
.bt-pg .bt-qv:checked~.bt-tc-media .bt-seg label{min-height:56px;font-size:12px;letter-spacing:.2em}
.bt-pg .bt-qv:checked~.bt-pc-b{position:relative;display:block;min-width:0;overflow-y:auto;padding:clamp(28px,3.2vw,48px) clamp(24px,3vw,48px) clamp(28px,3vw,44px);overscroll-behavior:contain}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-pc-k{padding-right:52px;font-size:11px}
.bt-pg .bt-qv:checked~.bt-pc-b h3{font-size:clamp(34px,3.3vw,50px);line-height:1.06;margin:10px 0 8px}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-pc-m{font-size:15px}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-pc-p{font-size:14px;margin:18px 0 22px;padding-top:16px;border-top:1px solid var(--line)}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-pc-p b{font-size:32px}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-card-only{display:none}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-qv-only{display:block}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-qv-x{display:flex}
.bt-pg .bt-qv-x{position:absolute;right:14px;top:14px;z-index:3;width:44px;height:44px;align-items:center;justify-content:center;cursor:pointer;color:var(--ink);background:rgba(249,244,236,.9);transition:color .3s,transform .6s var(--ease)}
.bt-pg .bt-qv-x:hover{color:var(--navy);transform:rotate(90deg)}
.bt-pg .bt-qv-desc{font-size:16.5px;line-height:1.65;color:var(--body);margin:0 0 22px}
.bt-pg .bt-tc .bt-spec{width:100%;border-collapse:collapse;font-size:15px;margin:0 0 22px}
.bt-pg .bt-tc .bt-spec th,.bt-pg .bt-tc .bt-spec td{text-align:left;vertical-align:top;padding:10px 0;border-top:1px solid var(--line);border-bottom:0;font-weight:400}
.bt-pg .bt-tc .bt-spec tr:first-child th,.bt-pg .bt-tc .bt-spec tr:first-child td{border-top:1px solid var(--line)}
.bt-pg .bt-tc .bt-spec tr:last-child th,.bt-pg .bt-tc .bt-spec tr:last-child td{border-bottom:1px solid var(--line)}
.bt-pg .bt-tc .bt-spec th{width:36%;font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);padding-top:13px}
.bt-pg .bt-tc .bt-spec td b{font-weight:500;color:var(--navy)}
.bt-pg .bt-tc .bt-calc{background:var(--sand);border:0;padding:18px 20px;margin:0 0 22px}
.bt-pg .bt-tc .bt-calc-row{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:14px}
.bt-pg .bt-tc .bt-calc label{display:block;font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut)}
.bt-pg .bt-tc .bt-calc select,.bt-pg .bt-tc .bt-calc input{display:block;width:100%;min-width:0;height:48px;margin-top:8px;border:1px solid var(--line);border-radius:0;background:#fff;padding:0 12px;font-family:var(--sans);font-size:16px;color:var(--ink);letter-spacing:0;text-transform:none}
.bt-pg .bt-tc .bt-calc output{display:block;margin-top:14px;font-size:15px;color:var(--body)}
.bt-pg .bt-tc .bt-calc output b{font-weight:500;color:var(--navy)}
.bt-pg .bt-qv-cta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px}
.bt-pg .bt-qv-cta .bt-btn{padding:0 14px;font-size:11.5px;letter-spacing:.16em}
.bt-pg .bt-qv-links{display:flex;flex-wrap:wrap;gap:10px 26px;font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--navy);margin-bottom:20px}
.bt-pg .bt-qv-links a{border-bottom:1px solid currentColor;padding-bottom:4px}
.bt-pg .bt-qv-note{font-size:13.5px;line-height:1.55;color:rgba(29,30,31,.6)}
@media (max-width:860px){
.bt-pg .bt-tc:has(>.bt-qv:checked){left:0;top:0;transform:none;width:100%;height:100%;display:block;overflow-y:auto;animation-name:btQvM}
.bt-pg .bt-qv:checked~.bt-tc-media{display:block}
.bt-pg .bt-qv:checked~.bt-tc-media .bt-tc-imgs{aspect-ratio:4/3;flex:none}
.bt-pg .bt-qv:checked~.bt-pc-b{overflow:visible;padding:24px var(--gut) 110px}
.bt-pg .bt-qv:checked~.bt-pc-b .bt-pc-cta{flex-wrap:nowrap}
}
@media (max-width:760px){
.bt-pg .bt-seg label{min-height:38px;font-size:9.5px;letter-spacing:.1em}
.bt-pg .bt-qv-long{display:none}
.bt-pg .bt-qv-cta{grid-template-columns:1fr}
.bt-pg .bt-tc .bt-calc-row{grid-template-columns:1fr}
.bt-pg .bt-qv:checked~.bt-tc-media .bt-seg label{min-height:50px;font-size:11px;letter-spacing:.16em}
}
.bt-pg .bt-sechead{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:18px 30px;margin-bottom:clamp(26px,3.2vw,46px)}
